def _coordinates(study, raw):
    from scipy.optimize import minimize_scalar
    x = _latent(study, raw)
    ops = []
    for (panel, key, fun, br) in [('panel_b', 'v', lambda z, a: np.tanh(a * z), (0.5, 2.5)), ('panel_c', 'v1', lambda z, a: z / (1 + a * abs(z)), (0.2, 2.0)), ('panel_c', 'v2', lambda z, a: np.cos(a * z), (0.5, 2.2))]:
        p = study[panel]
        (u, v) = (p['u'], p[key])
        f = lambda z, a: _aff(np.c_[z, fun(z, a)])

        def obj(a):
            m = f(u, a)
            return np.linalg.norm(v - m @ _ls(m, v))
        a = minimize_scalar(obj, bounds=br, method='bounded').x
        b = _ls(f(u, a), v)
        ops.append(lambda z, f=f, a=a, b=b: f(z, a) @ b)
    (b, c, d) = (op(x) for op in ops)
    return {'x': x, 'b': b, 'c': c, 'd': d, 'bc': ops[1](b), 'bd': ops[2](b), 'cb': ops[0](c), 'cd': ops[2](c), 'db': ops[0](d), 'dc': ops[1](d)}

def solve_batch(study: dict) -> dict:
    from scipy.optimize import least_squares
    train = study['train']
    raw = np.r_[train['x'], study['test']['x']]
    D = _coordinates(study, raw)
    times = study['eval_times']
    T = train['traj']
    Y = np.c_[train['y'], T]
    (k, h) = study['telemetry_vec'][:2]
    out = _adaptive(D, Y, k, h)

    def basis(r):
        return np.array([times, -np.expm1(-r[0] * times), -np.expm1(-r[1] * times)])

    def res(r):
        b = basis(r)
        return (T - _ls(b.T, T.T).T @ b).ravel()
    r = least_squares(res, [0.8, 7], bounds=([0.1, 2], [2, 20])).x
    b = basis(r)
    y = out[:, 0].copy()
    p = _ls(b.T, out[:, 1:].T).T @ b
    return {'y_hat': y, 'state_pred': p, 'diagnostics_vec': np.array([y.mean(), y.std(), p[:, -1].mean(), p[:, -1].std()])}
